class TaskListener(EventListener):

    @abstractmethod
    def taskStarted(self, te):
        pass

    @abstractmethod
    def taskFinished(self, te):
        pass

    # is called when the status of the task has advanced.
    # @param te
    @abstractmethod
    def taskStatusChanged(self, te):
        pass
